// The Q2 2026 Quarterly Report.
//
// Q2 is not generated by the reporting service (the pipeline first ran after the quarter closed, so a
// generated report for it is empty). It is a fixed snapshot of the Inventory Planning Overview's own
// figures -- the same definitions, taken from the same recommendations -- saved once and shown as a report
// in its own right next to the generated ones. Nothing here is fetched when the page opens.
//
// This file is the logic around that snapshot: the data's shape, picking one plant / type scope out of it,
// and turning a scope into what the Overview's own components take.

import type { PlantPosition, PositionScope } from "@/features/initiative-7/utils/plant-position"
import { POSITION_SCOPES } from "@/features/initiative-7/utils/plant-position"

export const SNAPSHOT_QUARTER = "Q2 2026"

/** Shown on the landing card in place of "Generated <date>". */
export const SNAPSHOT_CAPTION = "Overview figures, October 2026 run"

/** The Overview's Recommendation filter: both, OAR only, or stock items (everything that is not OAR). */
export type SnapshotType = "all" | "oar" | "stock_item"

export const SNAPSHOT_TYPES: { value: SnapshotType; label: string }[] = [
  { value: "all", label: "All" },
  { value: "oar", label: "OAR" },
  { value: "stock_item", label: "Stock item" },
]

/** The Overview's figures for one scope. A `null` is a figure that was not captured -- shown as "Not
 * available", never as 0. */
export interface SnapshotFigures {
  /** Recommendations in scope: the denominator of the excess share. */
  total: number
  stockout_at_risk: number
  stockout_evaluated: number
  stockout_insufficient_data: number
  /** ISO date the usage was read as of; null = the usage has not been built. */
  stockout_as_of: string | null
  excess_count: number
  excess_opportunity: number | null
  /** SUM(unit_price x (current - recommended ROP)): positive releases working capital. */
  net_rop_value_impact: number | null
  /** Recommendations with something to adopt: the "of y" on the Adopted card. */
  adoption_total: number | null
  adopted: number | null
  partially_adopted: number | null
  not_adopted: number | null
  pending: number | null
}

export type StockLevelKey = "ss" | "rop" | "max"

export interface SnapshotStockLevel {
  key: StockLevelKey
  current: number | null
  recommended: number | null
}

export interface SnapshotMaterial {
  matnr: string
  desc: string
  plant: string
  crit: string
  pattern: string
  rop_cur: number | null
  rop_rec: number | null
  status: string
}

export interface SnapshotScope {
  /** One SAP plant code; null is every plant. */
  plant: string | null
  type: SnapshotType
  figures: SnapshotFigures
  /** Mean current and recommended levels over the recommendations with something to adopt. null = not captured. */
  stock_levels: SnapshotStockLevel[] | null
  /** How many recommendations those means are over. */
  stock_levels_count: number | null
  /** The newest recommendations with something to adopt -- a subset, listed in `materials_total`. */
  materials: SnapshotMaterial[] | null
  materials_total: number | null
}

export interface QuarterlySnapshot {
  quarter: string
  period: string
  /** What the figures are from, e.g. "October 2026 run". */
  source: string
  /** ISO date the figures were taken. */
  captured_at: string
  currency: string | null
  scopes: SnapshotScope[]
}

/** Loaded on demand: a separate chunk, fetched only when the Q2 report is opened. */
export async function loadQuarterlySnapshot(): Promise<QuarterlySnapshot> {
  const data = await import("@/features/initiative-7/data/quarterly-q2-2026.json")
  return data.default as unknown as QuarterlySnapshot
}

/** The scope for a plant (null = every plant) and a type, or undefined when it was not captured. */
export function findScope(
  snapshot: QuarterlySnapshot,
  plant: string | null,
  type: SnapshotType,
): SnapshotScope | undefined {
  return snapshot.scopes.find((scope) => scope.plant === plant && scope.type === type)
}

/** One bar per plant scope for the type chosen, as the Overview's plant cards take them: All plants, 1300,
 * 1500 -- or only the plant picked. A scope that was not captured is left out rather than drawn as 0. */
export function plantPositions(snapshot: QuarterlySnapshot, type: SnapshotType, plant: string | null): PlantPosition[] {
  const scopes: PositionScope[] = plant ? [plant as PositionScope] : POSITION_SCOPES
  return scopes.flatMap((scope) => {
    const found = findScope(snapshot, scope === "ALL" ? null : scope, type)
    if (!found) return []
    const f = found.figures
    return [
      {
        scope,
        total: f.total,
        stockoutRisk: f.stockout_at_risk,
        stockoutEvaluated: f.stockout_evaluated,
        stockoutAsOf: f.stockout_as_of,
        excess: f.excess_count,
      },
    ]
  })
}

/** The shape the Overview's SAP adoption card takes, or null when adoption was not captured. */
export function adoptionOf(figures: SnapshotFigures) {
  if (figures.adoption_total === null) return null
  const adopted = figures.adopted ?? 0
  const partially = figures.partially_adopted ?? 0
  const known = adopted + partially + (figures.not_adopted ?? 0)
  return {
    totalEvaluated: figures.adoption_total,
    adoptedCount: adopted,
    partiallyAdoptedCount: partially,
    notAdoptedCount: figures.not_adopted ?? 0,
    unknownCount: figures.pending ?? 0,
    // Over the ones with SAP evidence only, as the backend's own rate is; null while there is none.
    adoptionRatePercentage: known > 0 ? Math.round(((adopted + partially) / known) * 1000) / 10 : null,
  }
}

// --- Stock levels ------------------------------------------------------------------------------------

export const STOCK_LEVEL_LABELS: Record<StockLevelKey, { label: string; hint: string }> = {
  ss: { label: "Safety stock", hint: "demand buffer" },
  rop: { label: "Reorder point", hint: "when to raise a PO" },
  max: { label: "Maximum stock", hint: "ceiling to hold" },
}

/** The three levels in the order the table lists them, each with its change; a level without both values has
 * no change. */
export function stockLevelRows(levels: SnapshotStockLevel[] | null) {
  const order: StockLevelKey[] = ["ss", "rop", "max"]
  return order.map((key) => {
    const found = levels?.find((level) => level.key === key)
    const current = found?.current ?? null
    const recommended = found?.recommended ?? null
    return {
      key,
      ...STOCK_LEVEL_LABELS[key],
      current,
      recommended,
      delta: current !== null && recommended !== null ? recommended - current : null,
    }
  })
}

// --- Paging ------------------------------------------------------------------------------------------

export function pageOf<T>(rows: T[], page: number, pageSize: number): T[] {
  const start = (page - 1) * pageSize
  return rows.slice(start, start + pageSize)
}

export function pageCount(total: number, pageSize: number): number {
  return Math.max(1, Math.ceil(total / pageSize))
}

// --- Which quarters the landing grid offers ----------------------------------------------------------

/** Quarters kept off the landing grid. Q3 2026's and Q4 2026's generated reports are not shown. */
export const HIDDEN_QUARTERS: readonly string[] = ["Q3 2026", "Q4 2026"]

/**
 * The generated reports' quarters plus the Q2 snapshot, newest first, without the hidden ones. The snapshot is
 * always offered: it is not generated, so it is not in the list the backend returns.
 */
export function landingQuarters(generated: string[]): string[] {
  const key = (quarter: string) => {
    const [q, year] = quarter.replace("Q", "").split(" ")
    return Number(year) * 10 + Number(q)
  }
  return Array.from(new Set([...generated, SNAPSHOT_QUARTER]))
    .filter((quarter) => !HIDDEN_QUARTERS.includes(quarter))
    .sort((a, b) => key(b) - key(a))
}
